    LearningHausQuestions.getStageQuestions = (chapter, stagePosition, limit = 10) => {
        const isFinalExam = stagePosition === LearningHausRules.quiz.stagesPerChapter - 1;
        const bank = isFinalExam
            ? LearningHausQuestions.finalExamByChapter[chapter] || LearningHausQuestions.warmUpByChapter[chapter]
            : LearningHausQuestions.warmUpByChapter[chapter];
        if (bank && bank.length > 0) {
            const converted = bank.map((q, idx) => toQuestion(q, chapter * 5 + idx + stagePosition + 1));
            const offset = stagePosition % converted.length;
            const rotated = [...converted.slice(offset), ...converted.slice(0, offset)];
            return rotated.slice(0, Math.min(limit, rotated.length));
        }
        const chapterPromptList = LearningHausQuestions.chapterPrompts[chapter] || [];
        if (chapter === 1) {
            return [...LearningHausQuestions.chapterOne.slice(stagePosition), ...LearningHausQuestions.chapterOne.slice(0, stagePosition)].slice(0, limit);
        }
        return chapterPromptList.map((pair, position) => LearningHausQuestions.buildQuestion(pair, position, stagePosition)).slice(0, limit);
    };
