        if (!page || !editorDialog || !passwordDialog || !accountDialog)
            return;
        const storageKey = "learninghaus.profile.v1";
        const phoneCountries = [
            { code: "+66", label: "Thailand (+66)" },
            { code: "+1", label: "United States / Canada (+1)" },
            { code: "+44", label: "United Kingdom (+44)" },
            { code: "+61", label: "Australia (+61)" },
            { code: "+65", label: "Singapore (+65)" },
            { code: "+81", label: "Japan (+81)" },
            { code: "+82", label: "South Korea (+82)" },
            { code: "+86", label: "China (+86)" },
            { code: "+33", label: "France (+33)" },
            { code: "+49", label: "Germany (+49)" }
        ];
        const defaults = {
            name: "TONOAK",
            level: "1",
            exp: LearningHausRules.level.initialExp,
            totalXp: LearningHausRules.level.initialExp,
            username: "TONOAKPAPAWIN048",
            email: "6631306048@lamduan.ac.mfu.th",
            phoneCountry: "+66",
            phone: "616844924",
            phoneVerified: false,
            emailVerified: false,
            about: "",
            facebook: "Papawin Namchue",
            facebookUrl: "https://www.facebook.com/",
            instagram: "it.papawin",
            instagramUrl: "https://www.instagram.com/",
            x: "KillSMz",
            xUrl: "https://x.com/",
            avatar: "",
            featuredAchievements: null,
            accountState: "active"
        };
        const normalizeFeatured = (value) => {
            if (value === null || value === undefined || value === "")
                return null;
            let parsed = value;
            if (typeof value === "string") {
                try {
                    parsed = JSON.parse(value);
                }
                catch {
                    return null;
                }
            }
            if (!Array.isArray(parsed))
                return null;
            const validIds = new Set(LearningHausAchievementCatalog.all.map((item) => item.id));
            const seen = new Set();
            const out = [];
            for (const entry of parsed) {
                const id = String(entry || "").trim();
                if (validIds.has(id) && !seen.has(id)) {
                    seen.add(id);
                    out.push(id);
                    if (out.length >= 3)
                        break;
                }
            }
            return out;
        };
        const resolveValidAvatar = (candidate) => {
            const headAvatar = window.LearningHausPixelCat?.getActiveAvatarDataUrl?.() || "";
            if (headAvatar)
                return headAvatar;
            const trimmed = String(candidate || "").trim();
            if (!trimmed || trimmed.includes("Profire/PF0"))
                return "";
            return trimmed;
        };
        let profile = { ...defaults, avatar: resolveValidAvatar("") };
        let editTarget = "";
        let accountAction = "";
